<?php
declare(strict_types=1);
session_start();
$config = __DIR__ . '/config.local.php';
$pdo = null;
if (is_file($config)) {
    require $config;
    try { $pdo = new PDO('mysql:host='.DB_HOST.';dbname='.DB_NAME.';charset=utf8mb4', DB_USER, DB_PASS, [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]); } catch (Throwable $e) { $dbError = 'No se pudo conectar con la base de datos.'; }
}
function h($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
$trips = [];
if ($pdo) { $sql="SELECT t.id,t.departure_at,t.status,o.city origin,d.city destination,r.duration_minutes,b.plate,b.deck_count,COUNT(s.id) seats,SUM(s.status='available') available,MIN(s.price) price FROM trips t JOIN routes r ON r.id=t.route_id JOIN terminals o ON o.id=r.origin_id JOIN terminals d ON d.id=r.destination_id JOIN buses b ON b.id=t.bus_id JOIN trip_seats s ON s.trip_id=t.id WHERE t.departure_at >= NOW() AND t.status='programado'"; $params=[]; if(!empty($_GET['origen'])){$sql.=' AND o.city=?';$params[]=trim($_GET['origen']);}if(!empty($_GET['destino'])){$sql.=' AND d.city=?';$params[]=trim($_GET['destino']);}if(!empty($_GET['fecha'])){$sql.=' AND DATE(t.departure_at)=?';$params[]=trim($_GET['fecha']);}$sql.=' GROUP BY t.id ORDER BY t.departure_at LIMIT 30';$q=$pdo->prepare($sql);$q->execute($params);$trips=$q->fetchAll(); }
if ($_SERVER['REQUEST_METHOD']==='POST' && $pdo) {
  $trip=(int)($_POST['trip_id']??0); $seat=(int)($_POST['seat_id']??0); $name=trim($_POST['passenger']??''); $dni=trim($_POST['dni']??''); $age=(int)($_POST['age']??0); $message='';
  if ($trip && $seat && $name && preg_match('/^[0-9]{8}$/',$dni) && $age>=1 && $age<=120) {
    try { $pdo->beginTransaction(); $q=$pdo->prepare("SELECT id,price,status,hold_until,hold_token,(hold_until>NOW()) AS hold_active FROM trip_seats WHERE id=? AND trip_id=? FOR UPDATE"); $q->execute([$seat,$trip]); $s=$q->fetch();
      $holdToken=$_POST['hold_token']??'';
      if (!$s || $s['status']!=='held' || (int)$s['hold_active']!==1 || !hash_equals((string)$s['hold_token'], $holdToken) || !hash_equals($_SESSION['seat_hold'][(string)$seat]??'', $holdToken)) throw new RuntimeException('Ese asiento ya no está disponible o venció la reserva. Actualiza el mapa.');
      $pdo->prepare("UPDATE trip_seats SET status='sold',hold_token=NULL,hold_until=NULL WHERE id=?")->execute([$seat]);
      $ticket=bin2hex(random_bytes(16)); $pdo->prepare("INSERT INTO passengers(dni,full_name,age) VALUES(?,?,?) ON DUPLICATE KEY UPDATE full_name=VALUES(full_name),age=VALUES(age)")->execute([$dni,$name,$age]);
      $p=$pdo->prepare('SELECT id FROM passengers WHERE dni=?'); $p->execute([$dni]); $passengerId=$p->fetchColumn();
      $pdo->prepare("INSERT INTO tickets(trip_id,trip_seat_id,passenger_id,price,status,qr_code,sold_by) VALUES(?,?,?,?,'valid',?,NULL)")->execute([$trip,$seat,$passengerId,$s['price'],$ticket]); $ticketId=$pdo->lastInsertId(); $method=$_POST['payment_method']??'cash';if(!in_array($method,['cash','card','transfer'],true))$method='cash';$pdo->prepare("INSERT INTO payments(ticket_id,method,amount,status) VALUES(?,?,?,'paid')")->execute([$ticketId,$method,$s['price']]); $pdo->commit(); $receiptUrl='boleto.php?id='.urlencode((string)$ticketId); if(defined('CENTRAL_PRINT_API_URL')&&CENTRAL_PRINT_API_URL!==''&&defined('CENTRAL_PRINT_SITE_TOKEN')&&CENTRAL_PRINT_SITE_TOKEN!==''&&defined('CENTRAL_PRINT_SUBMIT_TOKEN')&&CENTRAL_PRINT_SUBMIT_TOKEN!=='')$receiptUrl.='&central=1'; header('Location: '.$receiptUrl); exit;
    } catch (Throwable $e) { if ($pdo->inTransaction()) $pdo->rollBack(); $message=$e instanceof RuntimeException?$e->getMessage():'No se pudo completar la venta.'; }
  } else $message='Ingresa nombre, DNI de 8 dígitos y una edad válida.';
}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ruta Norte · Venta de pasajes</title><link rel="stylesheet" href="assets/app.css?v=20261028"></head><body>
<header class="top"><a class="brand" href="index.php"><span class="brand-icon">RN</span> RUTA<span>NORTE</span></a><nav><a class="active" href="#buscar">Buscar viajes</a><a href="manifiesto.php">Embarque</a><a href="reportes.php">Reportes</a><a href="pasajeros.php">Pasajeros</a><a href="simulador.php">Simulador</a></nav><div class="user"><span class="avatar">JV</span><span>Jhonny Vega<small>Vendedor · Counter</small></span></div></header>
<main><section class="hero"><div><div class="eyebrow"><i></i> TERMINAL TERRESTRE · LIMA</div><h1>Tu próximo viaje<br><em>empieza aquí.</em></h1><p>Rutas seguras, asientos cómodos y salidas todos los días.</p></div><div class="hero-art"><div class="sun"></div><div class="road"></div><div class="bus">▰</div><span class="route-label">LIMA <b>→</b> CUSCO</span></div></section>
<section id="buscar" class="search-card"><form method="get" action="#viajes"><label>ORIGEN<select name="origen"><option>Lima</option><option>Arequipa</option><option>Cusco</option><option>Trujillo</option></select></label><span class="swap">⇄</span><label>DESTINO<select name="destino"><option>Cusco</option><option>Arequipa</option><option>Lima</option><option>Trujillo</option></select></label><label>FECHA<input type="date" name="fecha" value="<?=h($_GET['fecha']??'')?>"></label><button class="search-btn">⌕ &nbsp; Buscar viajes</button></form></section>
<?php if (!empty($dbError) || !$pdo): ?><div class="notice"><b>Configura la base de datos para habilitar ventas.</b><p>Copia <code>config.example.php</code> como <code>config.local.php</code>, completa las credenciales y ejecuta <code>schema.sql</code>.</p></div><?php endif; ?>
<section id="viajes" class="results"><div class="section-head"><div><div class="eyebrow">SALIDAS DISPONIBLES</div><h2>Viajes próximos <span><?=count($trips)?></span></h2></div><a href="manifiesto.php">Ver manifiesto de embarque ↗</a></div>
<?php if (!$trips): ?><div class="empty">No hay viajes próximos configurados todavía. Ejecuta el script de base de datos para cargar los datos de demostración.</div><?php endif; ?>
<?php foreach($trips as $t): ?><article class="trip"><div class="trip-date"><b><?=date('d',strtotime($t['departure_at']))?></b><span><?=strtoupper(date('M',strtotime($t['departure_at'])))?></span></div><div class="trip-route"><strong><?=h($t['origin'])?> <i>→</i> <?=h($t['destination'])?></strong><small><?=floor($t['duration_minutes']/60)?> h <?=($t['duration_minutes']%60)?> min · <?=h($t['plate'])?> · <?=h($t['deck_count'])?> piso(s)</small></div><div class="trip-time"><b><?=date('H:i',strtotime($t['departure_at']))?></b><small>Salida</small></div><div class="availability"><b><?=h($t['available'])?></b><small>asientos disponibles</small></div><div class="trip-price"><small>Desde</small><b>S/ <?=number_format((float)$t['price'],2)?></b></div><button class="outline" onclick="openSeats(<?= (int)$t['id'] ?>,'<?=h($t['origin'])?>','<?=h($t['destination'])?>')">Elegir asiento <span>→</span></button></article><?php endforeach; ?></section>
<footer><span>© 2026 Ruta Norte</span><span>Hecho para viajar mejor <i>✦</i></span><span>Ayuda: (01) 555-0198</span></footer></main>
<dialog id="seatDialog"><form method="post" id="saleForm"><div class="modal-head"><div><div class="eyebrow">SELECCIONA TU ASIENTO</div><h2 id="modalTitle">Asientos</h2></div><button type="button" class="close" onclick="seatDialog.close()">×</button></div><input type="hidden" name="trip_id" id="tripId"><input type="hidden" name="hold_token" id="holdToken"><div id="seatMap" class="seat-map">Selecciona un viaje para cargar asientos.</div><div class="legend"><span><i class="available"></i> Disponible</span><span><i class="selected"></i> Seleccionado</span><span><i class="sold"></i> Vendido</span></div><div id="holdClock" class="hint">Al elegir asiento, se reserva por 10 minutos.</div><div class="fields"><label>Pasajero<input name="passenger" required placeholder="Nombre completo"></label><label>DNI<input name="dni" required maxlength="8" pattern="[0-9]{8}" placeholder="8 dígitos"></label><label>EDAD<input name="age" type="number" min="1" max="120" required placeholder="Edad"></label><label>PAGO<select name="payment_method"><option value="cash">Efectivo</option><option value="card">Tarjeta</option><option value="transfer">Transferencia</option></select></label></div><p class="error"><?=h($message??'')?></p><button class="search-btn full">Registrar venta y emitir boleto</button><small class="hint">La venta se confirma con bloqueo transaccional del asiento.</small></form></dialog>
<script>
const seatDialog=document.querySelector('#seatDialog');
let holdTimer=null;
function clearSeatSelection(){document.querySelector('input[name="seat_id"]')?.remove();document.querySelector('#holdToken').value='';document.querySelectorAll('.seat.picked').forEach(s=>s.classList.remove('picked'));if(holdTimer){clearInterval(holdTimer);holdTimer=null}}
async function loadSeatMap(id){const box=document.querySelector('#seatMap');box.textContent='Cargando mapa…';const response=await fetch('seats.php?trip='+encodeURIComponent(id),{cache:'no-store'});if(!response.ok)throw new Error('No se pudo consultar el mapa.');const data=await response.json();box.replaceChildren();for(const deck of data.decks){const section=document.createElement('div');section.className='deck';const heading=document.createElement('b');heading.textContent='PISO '+deck.level;const grid=document.createElement('div');grid.className='seat-grid';for(const seat of deck.seats){const button=document.createElement('button');button.type='button';button.className='seat '+seat.status;button.dataset.id=seat.id;button.textContent=seat.label;button.disabled=seat.status!=='available';button.addEventListener('click',()=>pickSeat(button));grid.append(button)}section.append(heading,grid);box.append(section)}if(!data.decks.length)box.textContent='Este viaje no tiene asientos configurados.'}
async function openSeats(id,from,to){clearSeatSelection();document.querySelector('#tripId').value=id;document.querySelector('#modalTitle').textContent=from+' → '+to;document.querySelector('#holdClock').textContent='Al elegir asiento, se reserva por 10 minutos.';if(!seatDialog.open)seatDialog.showModal();try{await loadSeatMap(id)}catch(e){document.querySelector('#seatMap').textContent='No se pudo cargar el mapa. Comprueba la conexión e inténtalo otra vez.'}}
async function pickSeat(button){if(button.disabled)return;clearSeatSelection();button.disabled=true;const clock=document.querySelector('#holdClock');clock.textContent='Reservando asiento…';const form=new FormData();form.set('trip_id',document.querySelector('#tripId').value);form.set('seat_id',button.dataset.id);try{const response=await fetch('hold.php',{method:'POST',body:form});const data=await response.json();if(!response.ok||!data.ok){clock.textContent=data.message||'No se pudo reservar el asiento. Actualiza el mapa.';await loadSeatMap(document.querySelector('#tripId').value);return}button.classList.add('picked');button.disabled=false;const input=document.createElement('input');input.type='hidden';input.name='seat_id';input.value=button.dataset.id;document.querySelector('#saleForm').append(input);document.querySelector('#holdToken').value=data.token;let remaining=data.expires_in||600;const updateClock=()=>{clock.textContent='Asiento reservado · '+Math.floor(remaining/60)+':'+String(remaining%60).padStart(2,'0')+' restantes'};updateClock();holdTimer=setInterval(()=>{remaining--;if(remaining<=0){clearInterval(holdTimer);holdTimer=null;clearSeatSelection();clock.textContent='La reserva venció. Elige nuevamente.';loadSeatMap(document.querySelector('#tripId').value).catch(()=>{});return}updateClock()},1000)}catch(e){clock.textContent='No se pudo conectar para reservar. Comprueba la conexión e inténtalo otra vez.';button.disabled=false}}
async function refreshSeatMap(){if(!seatDialog.open)return;const id=document.querySelector('#tripId').value;if(!id)return;try{const response=await fetch('seats.php?trip='+encodeURIComponent(id),{cache:'no-store'});if(!response.ok)return;const data=await response.json();const seats=new Map(data.decks.flatMap(deck=>deck.seats).map(seat=>[String(seat.id),seat]));document.querySelectorAll('.seat').forEach(button=>{const seat=seats.get(button.dataset.id);if(!seat)return;const picked=button.classList.contains('picked');button.classList.remove('available','held','sold');button.classList.add(seat.status);button.disabled=picked?false:seat.status!=='available'})}catch(e){}}
setInterval(refreshSeatMap,10000);
</script><?php if(!empty($message)):?><script>seatDialog.showModal();</script><?php endif;?></body></html>

